UPDATE rental_order o JOIN (SELECT COALESCE(SUM(IF(fund_component='deposit',amount_fen,0)),0) deposit,
    COALESCE(SUM(IF(fund_component='rent',amount_fen,0)),0) rent,COALESCE(SUM(amount_fen),0) total FROM order_deduction WHERE rental_order_id=#{order}
    AND deduction_status='confirmed') d SET o.deposit_deducted_amount_fen=d.deposit,o.rent_deducted_amount_fen=d.rent,o.total_deducted_amount_fen=d.total,
    o.deposit_status=IF(d.deposit=0,o.deposit_status,IF(d.deposit+o.deposit_refunded_amount_fen=o.deposit_paid_amount_fen,'settled','partially_deducted')),
    o.version=o.version+1,o.updated_at=#{at} WHERE id=#{order}
